sys_ux_client_script.script:
/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
	return `
 <!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Software Asset Management Flow</title>
    <style>
        body {
            font-family: 'verdana';
            margin: 0;
            padding: 0;
            background: linear-gradient(135deg, #e6f0fa 0%, #ffffff 100%);
            color: #34495e;
            line-height: 1.5;
            overflow-x: hidden;
        }
        .container {
            max-width: 1000px;
            margin: 10px auto;
            padding: 10px;
            position: relative;
        }
        h1 {
            text-align: center;
            color: #2c3e50;
            font-size:25px;
            margin-bottom: 40px;
            text-shadow: 1px 1px 3px rgba(0, 0, 0, 0.1);
        }
        h2 {
            color: #16a085;
            font-size: 17px;
            margin: 10px 0 10px;
            position: relative;
            padding-left: 20px;
            border-left: 4px solid #adbdf0;
        }
        .flow-section {
            background: rgba(230, 240, 250, 0.5);
            padding: 20px;
            margin: 20px 0;
            border-radius: 10px;
            box-shadow: 0 4px 6px rgba(0, 0, 0, 0.05);
            position: relative;
            animation: fadeIn 0.6s ease-out;
        }
        .flow-section::after {
            content: '↓';
            position: absolute;
            bottom: -30px;
            left: 50%;
            transform: translateX(-50%);
            font-size: 1.5em;
            color: #16a085;
            opacity: 0.7;
        }
        .flow-section:last-child::after {
            content: '';
        }
        .highlight {
            color: #080561;
<!--             font-weight: bold; -->
        }
        p {
            margin: 10px 0;
        }
        ul {
            list-style: none;
            padding: 0;
            margin: 10px 0;
        }
        ul li {
            margin: 3px 0;
            padding-left: 25px;
            position: relative;
        }
        ul li::before {
            content: '➔';
            color: #0a0a0a;
            position: absolute;
            left: 0;
            font-size: 1.2em;
        }
        .question {
            text-align: center;
            margin-top: 10px;
            font-size: 1.2em;
            color: #2c3e50;
            font-weight: bold;
        }
        @keyframes fadeIn {
            from { opacity: 0; transform: translateY(20px); }
            to { opacity: 1; transform: translateY(0); }
        }
    </style>
</head>
<body>
    <div class="container">
        <h1>Software Asset Management Flow</h1>

        <div class="flow-section">
            <h2>Core Workflow</h2>
            <p>The system handles three primary request types - <span class="highlight">Onboarding</span>, <span class="highlight">Offboarding</span>, and <span class="highlight">Transfer</span> - each following a structured approval and execution process.</p>
        </div>

        <div class="flow-section">
            <h2>Offboarding Request</h2>
            <p>Request submitted for employee software removal</p>
            <p>Automatic approval workflow initiated to employee's direct manager</p>
            <p><span class="highlight">Manager Review Process:</span></p>
            <ul>
                <li>Approved: IT Security team creates catalog task to remove specified software from user's device</li>
                <li>Rejected: Request automatically closed</li>
            </ul>
        </div>

        <div class="flow-section">
            <h2>Onboarding Request</h2>
            <p>Request submitted for new employee software provisioning</p>
            <p>Automatic approval workflow initiated to employee's direct manager</p>
            <p><span class="highlight">Manager Review Process:</span></p>
            <ul>
                <li>Approved: IT Security team creates catalog task to install required software on user's device</li>
                <li>Rejected: Request automatically closed</li>
            </ul>
        </div>

        <div class="flow-section">
            <h2>Transfer Request</h2>
            <p>Request submitted for employee software reconfiguration during team transition</p>
            <p>Automatic approval workflow initiated to employee's direct manager</p>
            <p><span class="highlight">Manager Review Process:</span></p>
            <ul>
                <li>Approved: IT Security team creates comprehensive catalog task to:</li>
                <ul>
                    <li>Audit and identify software to be removed</li>
                    <li>Determine software to be retained</li>
                    <li>Install new software required for the new team/role</li>
                </ul>
                <li>Rejected: Request automatically closed</li>
            </ul>
        </div>

        <div class="flow-section">
            <h2>Key Process Characteristics</h2>
            <ul>
                <li>Centralized approval mechanism</li>
                <li>Manager-driven decision making</li>
                <li>Standardized IT security task creation</li>
                <li>Automated workflow management</li>
                <li>Flexible handling of different employment transition scenarios</li>
            </ul>
        </div>

        <div class="flow-section">
            <h2>Workflow Benefits</h2>
            <ul>
                <li>Ensures proper software asset management</li>
                <li>Maintains security and compliance</li>
                <li>Streamlines software provisioning and deprovisioning</li>
                <li>Provides clear audit trail</li>
                <li>Reduces manual intervention</li>
            </ul>
        </div>


    </div>
</body>
</html>
  `;
}
